import{_ as a}from"./chunks/image3.B8UTGdq_.js";import{_ as n,o as t,c as i,ah as o}from"./chunks/framework.inWAIpeo.js";const p="/projects/PuppyPi/en/latest/assets/1.D9uOcRLm.gif",s="/projects/PuppyPi/en/latest/assets/image6.9TiMrWkb.png",r="/projects/PuppyPi/en/latest/assets/image7.BL7YEt4e.png",c="/projects/PuppyPi/en/latest/assets/image18.eOfjvM5H.png",l="/projects/PuppyPi/en/latest/assets/image20.Cpyw1yeL.png",v=JSON.parse('{"title":"8. ROS1-AI Stair Recognition and Negotiating Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/8.ROS1_AI_Stair_Recognition_and_Negotiating_Course.md","filePath":"docs/8.ROS1_AI_Stair_Recognition_and_Negotiating_Course.md"}'),h={name:"docs/8.ROS1_AI_Stair_Recognition_and_Negotiating_Course.md"};function d(g,e,u,m,_,b){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_8-ros1-ai-stair-recognition-and-negotiating-course" tabindex="-1">8. ROS1-AI Stair Recognition and Negotiating Course <a class="header-anchor" href="#_8-ros1-ai-stair-recognition-and-negotiating-course" aria-label="Permalink to &quot;8. ROS1-AI Stair Recognition and Negotiating Course&quot;">​</a></h1><h2 id="_8-1-stair-recognition" tabindex="-1">8.1 Stair Recognition <a class="header-anchor" href="#_8-1-stair-recognition" aria-label="Permalink to &quot;8.1 Stair Recognition&quot;">​</a></h2><h3 id="_8-1-1-program-logic" tabindex="-1">8.1.1 Program Logic <a class="header-anchor" href="#_8-1-1-program-logic" aria-label="Permalink to &quot;8.1.1 Program Logic&quot;">​</a></h3><p>Before the game, we need to DIY a stair. We can use 20mm height items as stair, such as board and sturdy box. And paste the red electrical tape on the border, because PuppyPi recognize the stair through recognizing the color.</p><p>Stair recognition process is as follow.</p><p>Firstly, program to recognize the color of line. Use Lab color space to convert the image from RGB into Lab. Then, perform binaryzation, corrosion, dilation, etc., on the image to obtain the contour which contains the target color. Next, mark the contour with rectangle.</p><p>Then, acquire the diagonal point of the rectangle and draw the center of the line. Lastly, display the information about the line center on the terminal.</p><h3 id="_8-1-2-operation-steps" tabindex="-1">8.1.2 Operation Steps <a class="header-anchor" href="#_8-1-2-operation-steps" aria-label="Permalink to &quot;8.1.2 Operation Steps&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The input command should be case and space sensitive.</p></section><p>(1) Turn on PuppyPi, and then connect to Raspberry Pi desktop through VNC.</p><p>(2) Click <img loading="lazy" height="74" width="81" src="'+a+`" style="width:70px;"> to open LX terminal.</p><p>(3) Input command and press Enter to start the game.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosrun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_advanced_functions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> negotiate_stairs_demo.py</span></span></code></pre></div><p>(4) If want to close this game, we can press &quot;<strong>Ctrl+C</strong>&quot;. If it fails to close the game, please try again.</p><h3 id="_8-1-3-program-outcome" tabindex="-1">8.1.3 Program Outcome <a class="header-anchor" href="#_8-1-3-program-outcome" aria-label="Permalink to &quot;8.1.3 Program Outcome&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The program is default to detect red.</p></section><p>Paste the red electrical tape on the boarder of the stair, and then place the stair in front of PuppyPi. After the game starts, PuppyPi will recognize the line. When recognized, it will be framed on the camera returned image and its center will be drawn.</p><h3 id="_8-1-4-program-analysis" tabindex="-1">8.1.4 Program Analysis <a class="header-anchor" href="#_8-1-4-program-analysis" aria-label="Permalink to &quot;8.1.4 Program Analysis&quot;">​</a></h3><p>The source code of this program is stored in <a href="../_static/source_code/ros1/puppy_advanced_functions_scripts.zip">/home/ubuntu/puppy_pi/src/puppy_advanced_functions/scripts/negotiate_stairs_demo.py</a></p><ul><li><strong>Import Function Package</strong></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import sys</span></span>
<span class="line"><span>import cv2</span></span>
<span class="line"><span>import time</span></span>
<span class="line"><span>import math</span></span>
<span class="line"><span>import threading</span></span>
<span class="line"><span>import numpy as np</span></span>
<span class="line"><span>from enum import Enum</span></span>
<span class="line"><span></span></span>
<span class="line"><span>from common import Misc</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import rospy</span></span>
<span class="line"><span>from std_srvs.srv import *</span></span>
<span class="line"><span>from sensor_msgs.msg import Image</span></span>
<span class="line"><span>from object_tracking.srv import *</span></span>
<span class="line"><span>from puppy_control.msg import Velocity, Pose, Gait</span></span>
<span class="line"><span>from puppy_control.srv import SetRunActionName</span></span></code></pre></div><p>Using import statements to import the required modules: math provides a range of mathematical functions and constants for related calculations; rospy is used for ROS communication.</p><p><code>from object_tracking.srv import *</code> imports services related to object tracking.</p><p><code>from puppy_control.msg import Velocity, Pose, Gait</code> imports services for controlling and transmitting the velocity, pose, and gait of the robot.</p><ul><li><strong>Image Processing</strong></li></ul><p>(1) Gaussian Filtering</p><p>Before converting the image from RGB into Lab space, denoise the image and use <code>GaussianBlur()</code> function in cv2 library for Gaussian filtering.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frame_gb = cv2.GaussianBlur(frame_resize, (3, 3), 3)</span></span></code></pre></div><p>The meaning of the parameters in bracket is as follow</p><p>The first parameter <code>frame_resize</code> is the input image</p><p>The second parameter <code>(3, 3)</code> is the size of Gaussian kernel</p><p>The third parameter <code>3</code> is the allowable range of variation around the average in Gaussian filtering. The larger the value, the larger the allowable range of variation</p><p>(2) Binaryzation Processing</p><p>Adopt inRange() function in cv2 library to perform binaryzation on the image.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> frame_mask = cv2.inRange(frame_lab,</span></span>
<span class="line"><span>                                 (color_range_list[detect_color][&#39;min&#39;][0],</span></span>
<span class="line"><span>                                  color_range_list[detect_color][&#39;min&#39;][1],</span></span>
<span class="line"><span>                                  color_range_list[detect_color][&#39;min&#39;][2]),</span></span>
<span class="line"><span>                                  (color_range_list[detect_color][&#39;max&#39;][0],</span></span>
<span class="line"><span>                                   color_range_list[detect_color][&#39;max&#39;][1],</span></span>
<span class="line"><span>                                   color_range_list[detect_color][&#39;max&#39;][2]))  #对原图像和掩模进行位运算(perform bitwise operation to original image and mask)</span></span></code></pre></div><p>The first parameter in the bracket is the input image. The second and the third parameters respectively are the lower limit and upper limit of the threshold. When the RGB value of the pixel is between the upper limit and lower limit, the pixel is assigned 1, otherwise, 0.</p><p>(3) Open Operation and Close Operation</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>To reduce interference and make the image smoother, it is necessary to process the image.</p></section><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opened = cv2.morphologyEx(frame_mask, cv2.MORPH_OPEN, np.ones((6, 6), np.uint8))  # 开运算(opening operation)</span></span>
<span class="line"><span>closed = cv2.morphologyEx(opened, cv2.MORPH_CLOSE, np.ones((6, 6), np.uint8))  # 闭运算(closing operation)</span></span></code></pre></div><p>cv2.MORPH_OPEN refers to open operation where corrosion will be conducted first, then dilation.</p><p>cv2.MORPH_CLOSE indicates close operation where dilation will be conducted first, then corrosion.</p><p>Take <code>opened = cv2.morphologyEx(frame_mask, cv2.MORPH_OPEN, np.ones((6, 6), np.uint8))</code> for example. The meaning of the parameters in bracket is as follow.</p><p>The first parameter <code>frame_mask</code> is the input image.</p><p>The second parameter <code>cv2.MORPH_OPEN</code> refers to processing method, open operation.</p><p>The third parameter <code>np.ones((6, 6), np.uint8)</code> is frame size.</p><p>(4) Acquire the Maximum Contour</p><p>After processing the image, acquire the contour of the target to be recognized, which involves <code>findContours()</code> function in cv2 library.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cnts = cv2.findContours(closed , cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_TC89_L1)[-2]#找出所有轮廓(find out all the contours)</span></span></code></pre></div><p>The first parameter in parentheses is the input image;</p><p>the second parameter is the retrieval mode of the contour;</p><p>the third parameter is the approximation method of the contour.</p><p>Find the contour of the maximum area among the obtained contours. To avoid interference, please set a minimum value. Only when the area is greater than this value, the target contour is valid.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 找出面积最大的轮廓(find out the contour with the maximal area)</span></span>
<span class="line"><span># 参数为要比较的轮廓的列表(the parameter is the list of contour to be compared)</span></span>
<span class="line"><span>def getAreaMaxContour(contours):</span></span>
<span class="line"><span>    contour_area_temp = 0</span></span>
<span class="line"><span>    contour_area_max = 0</span></span>
<span class="line"><span>    area_max_contour = None</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    for c in contours:  # 历遍所有轮廓(iterate through all contours)</span></span>
<span class="line"><span>        contour_area_temp = math.fabs(cv2.contourArea(c))  # 计算轮廓面积(calculate the contour area)</span></span>
<span class="line"><span>        if contour_area_temp &gt; contour_area_max:</span></span>
<span class="line"><span>            contour_area_max = contour_area_temp</span></span>
<span class="line"><span>            if contour_area_temp &gt;= 5:  # 只有在面积大于300时，最大面积的轮廓才是有效的，以过滤干扰(only when the area is greater than 50, the contour with the largest area is considered valid to filter out interference)</span></span>
<span class="line"><span>                area_max_contour = c</span></span>
<span class="line"><span>    return area_max_contour, contour_area_max  # 返回最大的轮廓(return the maximal contour)</span></span></code></pre></div><ul><li><strong>Acquire the Position</strong></li></ul><p>(1) Frame the Line</p><p>Call <code>drawContours()</code> function to set the rectangle pattern and frame the line.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cv2.drawContours(img, [box], -1, (0,0,255,255), 2)#画出四个点组成的矩形(draw a rectangle formed by the four points)</span></span></code></pre></div><p>(2) Draw the Center</p><p>Next, acquire the diagonal points of the rectangle, and draw the line center through <code>circle()</code> function.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>centerX = rect[0][0]</span></span>
<span class="line"><span>centerY = rect[0][1]</span></span>
<span class="line"><span>centerX = int(Misc.map(centerX, 0, size[0], 0, img_w))</span></span>
<span class="line"><span>centerY = int(Misc.map(centerY, 0, size[1], 0, img_h))</span></span>
<span class="line"><span>for i in range(4):</span></span>
<span class="line"><span>    box[i, 1] = int(Misc.map(box[i, 1], 0, size[1], 0, img_h))</span></span>
<span class="line"><span>for i in range(4):                </span></span>
<span class="line"><span>    box[i, 0] = int(Misc.map(box[i, 0], 0, size[0], 0, img_w))</span></span>
<span class="line"><span>            </span></span>
<span class="line"><span>cv2.drawContours(img, [box], -1, (0,0,255,255), 2)#画出四个点组成的矩形(draw a rectangle formed by the four points)</span></span>
<span class="line"><span>target_centre_point = [centerX, centerY]      </span></span>
<span class="line"><span>cv2.circle(img, (int(centerX), int(centerY)), 5, (0,0,255), -1)#画出中心点(draw the center point)</span></span></code></pre></div><h2 id="_8-2-stair-negotiating" tabindex="-1">8.2 Stair Negotiating <a class="header-anchor" href="#_8-2-stair-negotiating" aria-label="Permalink to &quot;8.2 Stair Negotiating&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>if PuppyPi&#39;s performance is not desired, we can close debugging interface according to &quot;<a href="#anchor_8_2_5"><strong>8.2.5 Function Extension -&gt; Close Debugging Interface</strong></a>&quot;.</p></section><h3 id="_8-2-1-program-logic" tabindex="-1">8.2.1 Program Logic <a class="header-anchor" href="#_8-2-1-program-logic" aria-label="Permalink to &quot;8.2.1 Program Logic&quot;">​</a></h3><p>Before the game, we need to DIY a stair. We can use 20mm height items as stair, such as board and sturdy box. And paste the red electrical tape on the border. Then PuppyPi will recognize the red tape and approach it to finish negotiating the stair.</p><p>Stair negotiating process is as follow.</p><p>Firstly, program to recognize the color of line. Use Lab color space to convert the image from RGB into Lab. Then, perform binaryzation, corrosion, dilation, etc., on the image to obtain the contour which contains the target color. Next, mark the contour with rectangle. And draw the center of line with red dot.</p><p>Next, control PuppyPi to approach the line center to come closer to the stair.</p><p>Lastly, control PuppyPi to negotiate the stair.</p><h3 id="_8-2-2-operation-steps" tabindex="-1">8.2.2 Operation Steps <a class="header-anchor" href="#_8-2-2-operation-steps" aria-label="Permalink to &quot;8.2.2 Operation Steps&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The input command should be case and space sensitive.</p></section><p>(1) Turn on PuppyPi, and then connect to Raspberry Pi desktop through VNC.</p><p>(2) Click <img loading="lazy" height="74" width="81" src="`+a+'" style="width:70px;"> to open command line terminal</p><p>(3) Input command and press Enter to start the game.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosrun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_advanced_functions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> negotiate_stairs_demo.py</span></span></code></pre></div><p>(4) If want to close this game, we can press &quot;<strong>Ctrl+C</strong>&quot;. If it fails to close the game, please try again.</p><h3 id="_8-2-3-program-outcome" tabindex="-1">8.2.3 Program Outcome <a class="header-anchor" href="#_8-2-3-program-outcome" aria-label="Permalink to &quot;8.2.3 Program Outcome&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The program is default to detect red.</p></section><p>Paste the red electrical tape on the boarder of the stair, and then place the stair in front of PuppyPi. After the game starts, PuppyPi will recognize the line, and then approach the center of the line to negotiate the stair.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+p+`"><h3 id="_8-2-4-program-analysis" tabindex="-1">8.2.4 Program Analysis <a class="header-anchor" href="#_8-2-4-program-analysis" aria-label="Permalink to &quot;8.2.4 Program Analysis&quot;">​</a></h3><p>The source code is located in: <a href="../_static/source_code/ros1/puppy_advanced_functions_scripts.zip">/home/ubuntu/puppy_pi/src/puppy_advanced_functions/scripts/negotiate_stairs_demo.py</a></p><ul><li><strong>Approach the Stair</strong></li></ul><p>After stair recognition, program PuppyPi to approach the stair according to the coordinate of the line center.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while(puppyStatus == PuppyStatus.LOOKING_FOR) :</span></span>
<span class="line"><span>    if target_centre_point != None and target_centre_point[1] &gt; 400:</span></span>
<span class="line"><span>        puppyStatus = PuppyStatus.FOUND_TARGET</span></span>
<span class="line"><span>        rospy.sleep(2.1) # 继续往前走一点(continue walking forward)</span></span>
<span class="line"><span>        PuppyVelocityPub.publish(x=0, y=0, yaw_rate = math.radians(0))</span></span>
<span class="line"><span>        up_stairs_time = time.time()</span></span>
<span class="line"><span>        break</span></span>
<span class="line"><span>            </span></span>
<span class="line"><span>     PuppyVelocityPub.publish(x=10, y=0, yaw_rate = math.radians(0))</span></span>
<span class="line"><span>            </span></span>
<span class="line"><span>     rospy.sleep(0.01)</span></span>
<span class="line"><span>     break</span></span></code></pre></div><p>Use <code>PuppyVelocityPub.publish()</code> function to control the running state of robotic dog.</p><p>Take <code>PuppyVelocityPub.publish(x=0, y=0, yaw_rate = math.radians(0))</code> as example. The meanings of the parameters within the parentheses are as follows:</p><p>The first parameter <code>x</code> is the speed in cm/s of moving straight. Moving forward is taken as the positive direction.</p><p>The second parameter <code>y</code> is the speed in cm/s of moving sideways. PuppyPi cannot move sideways, hence this parameter is useless.</p><p>The third parameter <code>yaw_rate</code> is the turning speed in rad/s. Counterclockwise direction is taken ad positive direction.</p><ul><li><strong>Negotiate the Stair</strong></li></ul><p>After PuppyPi approaches the stair, call the built-in action group &quot;<strong>up_stairs_2cm.d6ac</strong>&quot; to control it to negotiate the stair.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        while(puppyStatus == PuppyStatus.FOUND_TARGET) :</span></span>
<span class="line"><span>            runActionGroup_srv(&#39;up_stairs_2cm.d6ac&#39;,True)</span></span>
<span class="line"><span>            if time.time() - up_stairs_time &gt; 25:</span></span>
<span class="line"><span>                puppyStatus = PuppyStatus.DOWN_STAIRS</span></span>
<span class="line"><span>                PuppyPose = PP[&#39;Stand&#39;].copy()</span></span>
<span class="line"><span>                PuppyPosePub.publish(stance_x=PuppyPose[&#39;stance_x&#39;], stance_y=PuppyPose[&#39;stance_y&#39;], x_shift=PuppyPose[&#39;x_shift&#39;]</span></span>
<span class="line"><span>                    ,height=PuppyPose[&#39;height&#39;], roll=PuppyPose[&#39;roll&#39;], pitch=PuppyPose[&#39;pitch&#39;], yaw=PuppyPose[&#39;yaw&#39;], run_time = 500)</span></span>
<span class="line"><span>                rospy.sleep(0.5)</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        while(puppyStatus == PuppyStatus.DOWN_STAIRS) :</span></span>
<span class="line"><span>            PuppyVelocityPub.publish(x=14, y=0, yaw_rate = math.radians(0))</span></span>
<span class="line"><span>            rospy.sleep(0.1)</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if puppyStatusLast != puppyStatus:</span></span>
<span class="line"><span>            print(&#39;puppyStatus&#39;,puppyStatus)</span></span>
<span class="line"><span>        puppyStatusLast = puppyStatus</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if is_shutdown:break</span></span></code></pre></div><p><code>PuppyPosePub.publish()</code> function is used to control PuppyPi&#39;s moving posture.</p><p>Take<code>PuppyPosePub.publish(stance_x=PuppyPose[&#39;stance_x&#39;], stance_y=PuppyPose[&#39;stance_y&#39;], x_shift=PuppyPose[&#39;x_shift&#39;],height=PuppyPose[&#39;height&#39;],roll=PuppyPose[&#39;roll&#39;], pitch=PuppyPose[&#39;pitch&#39;], yaw=PuppyPose[&#39;yaw&#39;], run_time = 500)</code> for example. The meaning of the parameters in bracket is as follow.</p><p>The first parameter <code>stance_x</code> refers to the distance in cm that front legs and hind legs move in the opposite direction on x axis.</p><p>The second parameter <code>stance_y</code> refers to the distance in cm that front legs and hind legs move in the opposite direction on y axis. As there is no servo controlling legs to move along Y axis, this parameter is useless.</p><p>The third parameter <code>x_shift</code> is the distance that 4 legs move in the same direction on x axis. The smaller the value, the greater PuppyPi leans forward. The greater the value, the greater PuppyPi leans backward. We can adjust x_shift to balance PuppyPi during it is walking.</p><p>The fourth parameter <code>height</code> refers to PuppyPi&#39;s height that the perpendicular distance between foothold and the upper joint in cm.</p><p>The fifth parameter<code>roll</code> is PuppyPi&#39;s roll angle in degree.</p><p>The sixth parameter <code>pitch</code> is PuppyPi&#39;s pitch angle in degree.</p><p>The seventh parameter <code>yaw</code> is yaw angle in degree.</p><p>The eighth parameter <code>run_time</code> is the motion time in ms.</p><p id="anchor_8_2_5"></p><h3 id="_8-2-5-function-extension" tabindex="-1">8.2.5 Function Extension <a class="header-anchor" href="#_8-2-5-function-extension" aria-label="Permalink to &quot;8.2.5 Function Extension&quot;">​</a></h3><ul><li><strong>Close Debugging Interface</strong></li></ul><p>As the continuous refresh of debugging interface will occupy CPU of Raspberry Pi, we can close debugging interface to tackle choppy running.</p><p>(1) Input command and press Enter to edit the stair negotiating program.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_advanced_functions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> negotiate_stairs_demo.py</span></span></code></pre></div><p>(2) Next, jump to this line of code.</p><img loading="lazy" height="286" width="822" class="common_img" src="`+s+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>we can input the line code and press &quot;<strong>Shift+G</strong>&quot; to jump to the corresponding line. The numbering of code positions in the diagram is for reference only, please refer to the actual positions.</p></section><p>(3) Press <strong>&quot;i&quot;</strong> key to enter editing mode. Then add <strong>&quot;#&quot;</strong> in front of the codes in the red frame to comment.</p><img loading="lazy" height="310" width="824" class="common_img" src="'+r+'"><p>(4) After modification, press <strong>&quot;Esc&quot;</strong> and input <strong>&quot;:wq&quot;</strong> and press Enter to save and exit editing.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><p>(5) Input the command to restart the game and check PuppyPi&#39;s performance.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosrun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_advanced_functions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> negotiate_stairs_demo.py</span></span></code></pre></div><p>(6) If you need to view the debugging screen again (real-time feedback from the camera), you can uncomment the content boxed in step 3), i.e., remove the &quot;<strong>#</strong>&quot; in front of the code, then save, as shown in the following figure:</p><img loading="lazy" height="286" width="822" class="common_img" src="'+s+'"><ul><li><strong>Change Line Color</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The program is default to recognize red line. And we can change the color, for example black.</p></section><p>(1) Enter command and press Enter to edit the program file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_advanced_functions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> negotiate_stairs_demo.py</span></span></code></pre></div><p>(2) Next, jump to this line of code.</p><img loading="lazy" height="126" width="823" class="common_img" src="'+c+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>we can input the line code and press &quot;<strong>Shift+G</strong>&quot; to jump to the corresponding line.</p></section><p>(3) Press &quot;<strong>i</strong>&quot; key to enter editing mode. Modify &quot;<strong>red</strong>&quot; as &quot;<strong>black</strong>&quot;.</p><img loading="lazy" height="233" width="824" class="common_img" src="'+l+'"><p>(4) After modification, press <strong>&quot;Esc&quot;</strong> and input <strong>&quot;:wq&quot;</strong> and press Enter to save and exit editing.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><p>(5) Input command to restart the game and check PuppyPi&#39;s performance.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosrun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_advanced_functions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> negotiate_stairs_demo.py</span></span></code></pre></div>',132)])])}const k=n(h,[["render",d]]);export{v as __pageData,k as default};
